utton></form><form method="POST" action="{{ route('laporan.status',$l) }}">@csrf @method('PATCH')<input type="hidden" name="status" value="Ditolak"><button type="submit" class="reject">Tolak</button></form>@endif</div></td></tr>@empty<tr><td colspan="6" style="text-align:center;padding:28px;color:var(--p-muted)">Belum ada laporan masuk.</td></tr>@endforelse</tbody></table></div></div></section>
<section id="status" class="tab-panel"><div class="section-block"><div class="section-head-clean"><div><h2>Status Laporan</h2><p>Rekap laporan dari 4 Satlak yang sudah mendapat keputusan akhir (diterima/disetujui atau ditolak).</p></div></div><div class="clean-table-wrap"><table class="clean-table"><thead><tr><th>Satlak</th><th>Perihal</th><th>Tujuan</th><th>Status</th><th>Tanggal</th><th>Detail</th></tr></thead><tbody>@forelse($laporanPimpinanSatlak->filter(fn($l) => str_contains(strtolower($l->status),'tolak') || str_contains(strtolower($l->status),'setuj') || str_contains(strtolower($l->status),'diterima')) as $l)<tr><td class="sender">{{ $l->satuan->kode ?? $l->satuan->nama ?? '-' }}</td><td class="subject">{{ $l->perihal }}</td><td>{{ $l->tujuanSatuan->nama ?? '-' }}</td><td><span class="status-pill {{ str_contains(strtolower($l->status),'tolak') ? 'bad' : ((str_contains(strtolower($l->status),'setuj') || str_contains(strtolower($l->status),'diterima')) ? 'ok' : ((str_contains(strtolower($l->status),'revisi')) ? 'revisi' : 'wait')) }}">{{ $l->status }}</span></td><td>{{ $l->created_at->translatedFormat('d M Y H:i') }}</td><td><button type="button" class="detail-btn" onclick="openReportDetail(this)" data-id="{{ $l->id }}" data-pengirim="{{ e($l->satuan->nama ?? '-') }}" data-tujuan="{{ e($l->tujuanSatuan->nama ?? '-') }}" data-perihal="{{ e($l->perihal) }}" data-prioritas="{{ e($l->prioritas) }}" data-proyek="{{ e($l->proyek ?? '-') }}" data-tanggal="{{ e($l->created_at->translatedFormat('d M Y H:i')) }}" data-deskripsi="{{ e($l->deskripsi) }}" data-lampiran="{{ $l->lampiran_path ? e(asset('storage/'.$l->lampiran_path)) : '' }}" data-deletable="1">Detail</button></td></tr>@empty<tr><td colspan="6" style="text-align:center;padding:28px;color:var(--p-muted)">Belum ada laporan.</td></tr>@endforelse</tbody></table></div></div></section></div></div></main></div>
<script>
(function(){
  const sidebar=document.getElementById('sidebar');
  document.getElementById('menuBtn')?.addEventListener('click',()=>sidebar?.classList.toggle('open'));
  // Toggle collapse sidebar (termasuk resize .content/.pimp-page) ditangani
  // bareng oleh script siberadInitSidebarCollapse di dash-styles.blade.php.

  // Toggle & penerapan tema awal untuk tombol ini normalnya sudah ditangani
  // oleh initRoleUi() di partials/pengumuman-banner.blade.php (dijalankan
  // lebih dulu, ditandai lewat dataset.uiBound). Kalau dua listener klik
  // terpasang di tombol yang sama, keduanya saling membatalkan dalam satu
  // klik (ganti tema lalu langsung balik lagi) — makanya di-guard di sini.
  const themeBtn=document.getElementById('themeToggleBtn');
  if (themeBtn && !themeBtn.dataset.uiBound) {
    themeBtn.dataset.uiBound = '1';
    const THEME_KEY='siberad-theme';
    function applyTheme(theme){
      if(theme==='light') document.documentElement.setAttribute('data-theme','light');
      else document.documentElement.removeAttribute('data-theme');
      themeBtn.setAttribute('aria-pressed',theme==='light'?'true':'false');
    }
    let savedTheme='dark';
    try{savedTheme=localStorage.getItem(THEME_KEY)||'dark';}catch(e){}
    applyTheme(savedTheme);
    themeBtn.addEventListener('click',()=>{
      const current=document.documentElement.getAttribute('data-theme')==='light'?'light':'dark';
      const next=current==='light'?'dark':'light';
      try{localStorage.setItem(THEME_KEY,next);}catch(e){}
      applyTheme(next);
    });
  }

  const profileBtn=document.getElementById('profileMenuBtn'),drop=document.getElementById('profileDropdown'),profileMenu=document.getElementById('profileMenu');
  function closeProfile(){drop?.classList.remove('open');profileBtn?.classList.remove('open');profileBtn?.setAttribute('aria-expanded','false');}
  function openProfile(){drop?.classList.add('open');profileBtn?.classList.add('open');profileBtn?.setAttribute('aria-expanded','true');}
  // Sama seperti tema: toggle klik tombol profil juga sudah ditangani oleh
  // initRoleUi() di pengumuman-banner.blade.php. Guard dengan flag yang sama
  // supaya tidak dobel-bind.
  if (profileBtn && !profileBtn.dataset.uiBound) {
    profileBtn.dataset.uiBound = '1';
    profileBtn.addEventListener('click',e=>{e.stopPropagation();drop?.classList.contains('open')?closeProfile():openProfile()});
  }
  document.addEventListener('click',e=>{if(profileMenu&&!profileMenu.contains(e.target))closeProfile()});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeProfile()});

  window.openProfileModal=function(id){
    document.querySelectorAll('#profileModalOverlay .profile-dropdown-view').forEach(v=>v.style.display=v.id===id?'block':'none');
    document.getElementById('profileModalOverlay')?.classList.add('open');
    document.body.style.overflow='hidden';
  };
  document.getElementById('openProfilSayaBtn')?.addEventListener('click',e=>{e.stopPropagation();closeProfile();window.openProfileModal('profilePhotoView')});
  document.getElementById('openPengaturanBtn')?.addEventListener('click',e=>{e.stopPropagation();closeProfile();window.openProfileModal('profileSettingsView')});
  document.getElementById('openBantuanBtn')?.addEventListener('click',e=>{e.stopPropagation();closeProfile();window.openProfileModal('profileHelpView')});
  function closeProfileModal(){document.getElementById('profileModalOverlay')?.classList.remove('open');document.body.style.overflow='';}
  document.getElementById('profileModalCloseBtn')?.addEventListener('click',closeProfileModal);
  document.getElementById('profileModalOverlay')?.addEventListener('click',e=>{if(e.target.id==='profileModalOverlay')closeProfileModal()});

  const GROUP_STATE_KEY='siberad-pimpinan-group-';

  // Sidebar ciutkan: submenu grup dirender sebagai flyout (position:fixed)
  // supaya tidak kepotong overflow-x:hidden milik .side-nav. Posisinya
  // dihitung dari posisi tombol grup di layar setiap kali flyout dibuka,
  // sidebar diciutkan/dilebarkan, atau ukuran jendela berubah.
  function positionGroupFlyout(g){
    const subnav=g.querySelector('.side-subnav');
    const btn=g.querySelector('.side-nav-group-title');
    if(!subnav||!btn)return;
    if(!sidebar?.classList.contains('collapsed')||!g.classList.contains('open')){
      subnav.style.top='';subnav.style.left='';return;
    }
    const r=btn.getBoundingClientRect();
    subnav.style.top=r.top+'px';
    subnav.style.left=(r.right+8)+'px';
  }
  window.siberadRepositionSubnavFlyouts=function(){
    document.querySelectorAll('.side-nav-group').forEach(positionGroupFlyout);
  };
  window.addEventListener('resize',()=>window.siberadRepositionSubnavFlyouts());

  ['monitorGroup','reportGroup'].forEach(id=>{
    const g=document.getElementById(id),b=g?.querySelector('.side-nav-group-title');
    if(!g)return;
    let saved=null;try{saved=sessionStorage.getItem(GROUP_STATE_KEY+id)}catch(e){}
    if(saved==='closed')g.classList.remove('open');
    else if(saved==='open')g.classList.add('open');
    else if(sidebar?.classList.contains('collapsed')){
      // Belum ada preferensi tersimpan & sidebar lagi ciutkan: jangan buka
      // semua grup sekaligus (flyout-nya bakal numpuk). Biarkan tertutup;
      // restoreActiveTab() di bawah akan buka ulang grup yang memang berisi
      // tab yang lagi aktif.
      g.classList.remove('open');
    }
    b?.addEventListener('click',e=>{
      e.stopPropagation();
      const willOpen=!g.classList.contains('open');
      // Mode ciutkan: cuma satu flyout yang tampil, tutup grup lain dulu.
      if(willOpen&&sidebar?.classList.contains('collapsed')){
        document.querySelectorAll('.side-nav-group.open').forEach(other=>{
          if(other===g)return;
          other.classList.remove('open');
          try{sessionStorage.setItem(GROUP_STATE_KEY+other.id,'closed')}catch(err){}
          positionGroupFlyout(other);
        });
      }
      g.classList.toggle('open');
      try{sessionStorage.setItem(GROUP_STATE_KEY+id,g.classList.contains('open')?'open':'closed')}catch(e){}
      positionGroupFlyout(g);
    });
  });

  // Flyout submenu (mode ciutkan) ditutup kalau klik di luar, tekan Escape,
  // atau memilih salah satu link di dalamnya.
  document.addEventListener('click',e=>{
    if(!sidebar?.classList.contains('collapsed'))return;
    document.querySelectorAll('.side-nav-group.open').forEach(g=>{
      if(g.contains(e.target))return;
      g.classList.remove('open');
      try{sessionStorage.setItem(GROUP_STATE_KEY+g.id,'closed')}catch(err){}
      positionGroupFlyout(g);
    });
  });
  document.addEventListener('keydown',e=>{
    if(e.key!=='Escape'||!sidebar?.classList.contains('collapsed'))return;
    document.querySelectorAll('.side-nav-group.open').forEach(g=>{
      g.classList.remove('open');
      try{sessionStorage.setItem(GROUP_STATE_KEY+g.id,'closed')}catch(err){}
      positionGroupFlyout(g);
    });
  });
  document.querySelectorAll('.side-nav-group .side-sub-link').forEach(a=>a.addEventListener('click',()=>{
    if(!sidebar?.classList.contains('collapsed'))return;
    const g=a.closest('.side-nav-group');
    if(!g)return;
    g.classList.remove('open');
    try{sessionStorage.setItem(GROUP_STATE_KEY+g.id,'closed')}catch(err){}
    positionGroupFlyout(g);
  }));

  const ACTIVE_TAB_KEY='siberad-pimpinan-active-tab';
  function showSection(id,link,skipSave){
    document.querySelectorAll('.tab-panel').forEach(p=>p.classList.remove('active'));
    const el=document.getElementById(id);if(el)el.classList.add('active');
    document.querySelectorAll('.side-sub-link,.side-link').forEach(a=>a.classList.remove('active'));
    if(link)link.classList.add('active');
    sidebar?.classList.remove('open');
    window.scrollTo({top:0,behavior:'smooth'});
    if(!skipSave){try{sessionStorage.setItem(ACTIVE_TAB_KEY,id)}catch(e){}}
  }
  document.querySelectorAll('.side-link[href^="#"],.side-sub-link[href^="#"],.card-link[href^="#"]').forEach(a=>a.addEventListener('click',e=>{const id=a.getAttribute('href').slice(1);if(document.getElementById(id)){e.preventDefault();showSection(id,a)}}));

  (function restoreActiveTab(){
    let savedId=null;
    try{savedId=sessionStorage.getItem(ACTIVE_TAB_KEY)}catch(e){}
    if(!savedId||!document.getElementById(savedId))return;
    const link=document.querySelector('.side-link[href="#'+savedId+'"],.side-sub-link[href="#'+savedId+'"]');
    showSection(savedId,link,true);
    if(link){
      const group=link.closest('.side-nav-group');
      if(group){group.classList.add('open');if(group.id)try{sessionStorage.setItem(GROUP_STATE_KEY+group.id,'open')}catch(e){}positionGroupFlyout(group);}
    }
  })();

  document.querySelectorAll('.logout-form').forEach(form=>form.addEventListener('submit',e=>{if(!window.confirm('Keluar dari akun SIBERAD?'))e.preventDefault()}));

  window.openReportDetail=function(button){const modal=document.getElementById('reportDetailModal');document.getElementById('detailPengirim').textContent=button.dataset.pengirim||'-';document.getElementById('detailTujuan').textContent=button.dataset.tujuan||'-';document.getElementById('detailPerihal').textContent=button.dataset.perihal||'-';document.getElementById('detailPrioritas').textContent=button.dataset.prioritas||'-';document.getElementById('detailProyek').textContent=button.dataset.proyek||'-';document.getElementById('detailTanggal').textContent=button.dataset.tanggal||'-';document.getElementById('detailDeskripsi').textContent=button.dataset.deskripsi||'-';const lampiran=button.dataset.lampiran||'',wrap=document.getElementById('detailLampiranWrap'),link=document.getElementById('detailLampiran');if(lampiran){link.href=lampiran;wrap.style.display='block'}else{wrap.style.display='none'}const actionsEl=document.getElementById('detailActions')||modal?.querySelector('.modal-actions');if(actionsEl){if(button.dataset.deletable==='1'){actionsEl.innerHTML='<div class="action-row"><button type="button" class="reject" onclick="bukaHapusRiwayatPimpinan(\''+(button.dataset.id||'')+'\')">Hapus dari Riwayat</button></div>'}else if(button.dataset.readonly==='1'){actionsEl.innerHTML='<span class="report-detail-note" style="margin-right:auto;font-size:11px;color:var(--p-muted);">Mode pimpinan: aktivitas Satlak bersifat view-only.</span>'}else{actionsEl.innerHTML='<span class="readonly-note">Mode pimpinan: aktivitas Satlak bersifat view-only.</span>'}}modal?.classList.add('open')};
  document.getElementById('reportDetailClose')?.addEventListener('click',()=>document.getElementById('reportDetailModal')?.classList.remove('open'));
  document.getElementById('reportDetailModal')?.addEventListener('click',e=>{if(e.target.id==='reportDetailModal')e.currentTarget.classList.remove('open')});

  window.bukaHapusRiwayatPimpinan=function(id){if(!id)return;document.getElementById('formHapusRiwayatPimpinan').action='{{ url('/laporan') }}/'+id;document.getElementById('reportDetailModal')?.classList.remove('open');document.getElementById('hapusRiwayatModal')?.classList.add('open')};
  window.tutupHapusRiwayatPimpinan=function(){document.getElementById('hapusRiwayatModal')?.classList.remove('open')};
  document.getElementById('hapusRiwayatClose')?.addEventListener('click',()=>tutupHapusRiwayatPimpinan());
  document.getElementById('hapusRiwayatModal')?.addEventListener('click',e=>{if(e.target.id==='hapusRiwayatModal')tutupHapusRiwayatPimpinan()});

  const satlakLabels=@json($monitoringPimpinanSatlak->pluck('kode')->values());
  const satlakTotals=@json($monitoringPimpinanSatlak->pluck('total')->values());
  const statusData={menunggu:{{ $laporanPimpinanSatlak->filter(fn($l)=>$l->status==='Menunggu')->count() }},disetujui:{{ $laporanPimpinanSatlak->filter(fn($l)=>str_contains(strtolower((string)$l->status),'setuj') || str_contains(strtolower((string)$l->status),'diterima'))->count() }},ditolak:{{ $laporanPimpinanSatlak->filter(fn($l)=>str_contains(strtolower((string)$l->status),'tolak'))->count() }}};
  window.siberadCharts = window.siberadCharts || [];
  function makeStatusChart(id){const el=document.getElementById(id);if(!el||typeof Chart==='undefined')return;window.siberadCharts.push(new Chart(el,{type:'doughnut',data:{labels:['Menunggu','Disetujui','Ditolak'],datasets:[{data:[statusData.menunggu,statusData.disetujui,statusData.ditolak],backgroundColor:['#d4a017','#16834b','#c83b3b'],borderColor:'transparent',borderWidth:2}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}}}}))}
  function makeSatlakChart(id){const el=document.getElementById(id);if(!el||typeof Chart==='undefined')return;window.siberadCharts.push(new Chart(el,{type:'bar',data:{labels:satlakLabels,datasets:[{label:'Jumlah laporan',data:satlakTotals,backgroundColor:'#c97a00',borderRadius:7,maxBarThickness:42}]},options:{responsive:true,maintainAspectRatio:false,scales:{y:{beginAtZero:true,ticks:{precision:0},grid:{color:'rgba(127,127,127,.15)'}},x:{grid:{display:false}}},plugins:{legend:{display:false}}}}))}
  makeStatusChart('statusChart');makeSatlakChart('satlakChart');
})();
</script>
</body>
</html>
